    // The dark color mode.
    VisualSnapshot(id: "dark", mode: .dark, locale: "en", rightToLeft: false, textSize: .default),
    // The light color mode with increased contrast.
    VisualSnapshot(id: "light-hc", mode: .lightHighContrast, locale: "en", rightToLeft: false, textSize: .default),
    // The dark color mode with increased contrast.
    VisualSnapshot(id: "dark-hc", mode: .darkHighContrast, locale: "en", rightToLeft: false, textSize: .default),
    // Arabic, right to left. What leads in English is on the right.
    VisualSnapshot(id: "rtl", mode: .light, locale: "ar", rightToLeft: true, textSize: .default),
    // The largest text size. Text grows and wraps, and nothing is cut off.
    VisualSnapshot(id: "largest-text", mode: .light, locale: "en", rightToLeft: false, textSize: .largest),
    // Vietnamese. Letters with two diacritics stacked must not touch the next line.
    VisualSnapshot(id: "vi", mode: .light, locale: "vi", rightToLeft: false, textSize: .default),
    // Chinese (Simplified). Lines break between characters, not only at spaces.
    VisualSnapshot(id: "zh-hans", mode: .light, locale: "zh-Hans", rightToLeft: false, textSize: .default),
    // Japanese, in kanji and kana.
    VisualSnapshot(id: "ja", mode: .light, locale: "ja", rightToLeft: false, textSize: .default),
    // Korean, in Hangul.
    VisualSnapshot(id: "ko", mode: .light, locale: "ko", rightToLeft: false, textSize: .default),
    // English 40% longer, as many translations are.
